package remaining

import (
	"encoding/json"
	"math"
	"os"
	"strconv"
	"strings"
	"testing"
	"time"
)

// The corpus is generated by testdata/generate_recommendations_rules_golden.py
// from the LIVE reference evaluators. See that file for how it is built and why
// floats cross as hex.

type goldenEnvironment struct {
	PythonVersion  string `json:"python_version"`
	Implementation string `json:"implementation"`
	Machine        string `json:"machine"`
	UnicodeVersion string `json:"unicode_version"`
	FloatReprStyle string `json:"float_repr_style"`
}

type goldenEvidence struct {
	TeamID      string `json:"team_id"`
	MetricTable string `json:"metric_table"`
	WindowStart string `json:"window_start"`
	WindowEnd   string `json:"window_end"`
	Field       string `json:"field"`
	ValueHex    string `json:"value_hex"`
	ValueBits   string `json:"value_bits"`
	ValueType   string `json:"value_type"`
}

type goldenResult struct {
	RuleID           string           `json:"rule_id"`
	TeamID           string           `json:"team_id"`
	OrgID            string           `json:"org_id"`
	Severity         string           `json:"severity"`
	Title            string           `json:"title"`
	Rationale        string           `json:"rationale"`
	SuccessCriterion string           `json:"success_criterion"`
	Evidence         []goldenEvidence `json:"evidence"`
}

type goldenSnapshot struct {
	TeamID                 string   `json:"team_id"`
	OrgID                  string   `json:"org_id"`
	WindowStart            string   `json:"window_start"`
	WindowEnd              string   `json:"window_end"`
	WIPByDay               []string `json:"wip_by_day"`
	ThroughputByCycle      []string `json:"throughput_by_cycle"`
	ReviewLatencyP75Hours  *string  `json:"review_latency_p75_hours"`
	ReviewerGini           *string  `json:"reviewer_gini"`
	ReworkChurnRatio       *string  `json:"rework_churn_ratio"`
	AfterHoursRatio        *string  `json:"after_hours_ratio"`
	CycleTimeByDay         []string `json:"cycle_time_by_day"`
	HotspotComplexityDelta *string  `json:"hotspot_complexity_delta"`
	HotspotChurnOverlap    *string  `json:"hotspot_churn_overlap"`
	CompoundingRiskScore   *string  `json:"compounding_risk_score"`
	// A JSON null here is Python's None; the Go mirror represents it as "".
	// Kept as a pointer so a null and an empty string stay distinguishable in
	// the fixture even though both map to "" -- the corpus contains BOTH
	// (severity None and severity "") and they must produce the same outcome
	// for the right reason, not by the decoder erasing the difference.
	CompoundingRiskSeverity *string `json:"compounding_risk_severity"`
}

type goldenCase struct {
	Name     string                   `json:"name"`
	Snapshot goldenSnapshot           `json:"snapshot"`
	Results  map[string]*goldenResult `json:"results"`
}

type goldenDocument struct {
	EvidenceValuesTypeChecked int               `json:"evidence_values_type_checked"`
	Environment               goldenEnvironment `json:"environment"`
	RuleOrder                 []string          `json:"rule_order"`
	SuccessCriteria           map[string]string `json:"success_criteria"`
	Cases                     []goldenCase      `json:"cases"`
}

func loadRulesGolden(t *testing.T) goldenDocument {
	t.Helper()
	raw, err := os.ReadFile("testdata/recommendations_rules_golden.json")
	if err != nil {
		t.Fatalf("read corpus: %v", err)
	}
	var document goldenDocument
	if err := json.Unmarshal(raw, &document); err != nil {
		t.Fatalf("decode corpus: %v", err)
	}
	return document
}

// parsePythonHexFloat decodes float.hex() output.
//
// The hex form is used precisely because it is exact in both directions:
// strconv.ParseFloat and Python's float() disagree on some decimal spellings
// (lane-4441, CHAOS-4840), but a hex literal names a bit pattern, so there is
// no rounding step for them to disagree about.
func parsePythonHexFloat(t *testing.T, text string) float64 {
	t.Helper()
	value, err := strconv.ParseFloat(text, 64)
	if err != nil {
		t.Fatalf("parse hex float %q: %v", text, err)
	}
	return value
}

// parseGoldenBits decodes the exact IEEE-754 bit pattern the reference produced.
//
// This is the authoritative decoder for evidence values, and value_hex is only
// a cross-check, because float.hex() is exact for every float EXCEPT NaN --
// it renders any NaN as bare "nan", dropping the payload.
//
// That elision produced this file's only failure: strconv.ParseFloat("nan")
// returns Go's math.NaN(), 0x7ff8000000000001, while the NaN that actually
// flows out of the slope arithmetic is the hardware default 0x7ff8000000000000.
// Four cases "failed" on a difference neither implementation had -- the fixture
// had invented it by round-tripping through a lossy spelling.
//
// The obvious repair was to exempt NaN payloads from the comparison. That would
// have been wrong: with the exact bits recorded, CPython's NaN here is
// 0x7ff8000000000000 too, so the two agree exactly and the strict assertion
// holds. Relaxing the comparison would have discarded a real property to work
// around a defect in the oracle.
func parseGoldenBits(t *testing.T, text string) float64 {
	t.Helper()
	bits, err := strconv.ParseUint(text, 16, 64)
	if err != nil {
		t.Fatalf("parse bit pattern %q: %v", text, err)
	}
	return math.Float64frombits(bits)
}

func parseOptional(t *testing.T, text *string) (float64, bool) {
	t.Helper()
	if text == nil {
		return 0, false
	}
	return parseGoldenBits(t, *text), true
}

func parseList(t *testing.T, texts []string) []float64 {
	t.Helper()
	values := make([]float64, len(texts))
	for index, text := range texts {
		values[index] = parseGoldenBits(t, text)
	}
	return values
}

func parseDate(t *testing.T, text string) time.Time {
	t.Helper()
	value, err := time.ParseInLocation("2006-01-02", text, time.UTC)
	if err != nil {
		t.Fatalf("parse date %q: %v", text, err)
	}
	return value
}

func decodeSnapshot(t *testing.T, encoded goldenSnapshot) MetricsSnapshot {
	t.Helper()
	latency, latencyKnown := parseOptional(t, encoded.ReviewLatencyP75Hours)
	gini, giniKnown := parseOptional(t, encoded.ReviewerGini)
	churn, churnKnown := parseOptional(t, encoded.ReworkChurnRatio)
	afterHours, afterHoursKnown := parseOptional(t, encoded.AfterHoursRatio)
	complexity, complexityKnown := parseOptional(t, encoded.HotspotComplexityDelta)
	overlap, overlapKnown := parseOptional(t, encoded.HotspotChurnOverlap)
	score, scoreKnown := parseOptional(t, encoded.CompoundingRiskScore)

	severity := ""
	if encoded.CompoundingRiskSeverity != nil {
		severity = *encoded.CompoundingRiskSeverity
	}

	return MetricsSnapshot{
		TeamID:                      encoded.TeamID,
		OrgID:                       encoded.OrgID,
		WindowStart:                 parseDate(t, encoded.WindowStart),
		WindowEnd:                   parseDate(t, encoded.WindowEnd),
		WIPByDay:                    parseList(t, encoded.WIPByDay),
		ThroughputByCycle:           parseList(t, encoded.ThroughputByCycle),
		ReviewLatencyP75Hours:       latency,
		ReviewLatencyP75HoursKnown:  latencyKnown,
		ReviewerGini:                gini,
		ReviewerGiniKnown:           giniKnown,
		ReworkChurnRatio:            churn,
		ReworkChurnRatioKnown:       churnKnown,
		AfterHoursRatio:             afterHours,
		AfterHoursRatioKnown:        afterHoursKnown,
		CycleTimeByDay:              parseList(t, encoded.CycleTimeByDay),
		HotspotComplexityDelta:      complexity,
		HotspotComplexityDeltaKnown: complexityKnown,
		HotspotChurnOverlap:         overlap,
		HotspotChurnOverlapKnown:    overlapKnown,
		CompoundingRiskScore:        score,
		CompoundingRiskScoreKnown:   scoreKnown,
		CompoundingRiskSeverity:     severity,
	}
}

// TestRuleOrderMatchesTheReference pins the emission order.
//
// This is not cosmetic. The engine writes one row per rule per team in
// iteration order, and the reference's order is its dict's insertion order --
// which is a language guarantee it relies on, and which a Go map would not
// reproduce. A reordering would be invisible to every per-rule assertion below
// and visible in the stored table.
func TestRuleOrderMatchesTheReference(t *testing.T) {
	document := loadRulesGolden(t)

	if len(document.RuleOrder) != len(orderedRuleEvaluators) {
		t.Fatalf("reference declares %d rules, the port has %d",
			len(document.RuleOrder), len(orderedRuleEvaluators))
	}
	for index, ruleID := range document.RuleOrder {
		if orderedRuleEvaluators[index].id != ruleID {
			t.Errorf("position %d: reference has %q, the port has %q",
				index, ruleID, orderedRuleEvaluators[index].id)
		}
	}
}

// TestSuccessCriteriaMatchTheReference compares the module-level constants
// directly, independently of whether any case fires.
//
// Worth its own test because these strings are built once at import from the
// thresholds and then copied onto every fired row. Two of the five were wrong
// in the port's first draft -- paraphrased from each rule's firing logic rather
// than copied from the string -- and both paraphrases were plausible enough to
// survive a read-through. A rule that never fires in the corpus would pin its
// criterion nowhere else.
func TestSuccessCriteriaMatchTheReference(t *testing.T) {
	document := loadRulesGolden(t)

	ported := map[string]string{
		"saturation":           saturationSuccessCriterion,
		"review-concentration": reviewConcentrationSuccessCriterion,
		"thrash":               thrashSuccessCriterion,
		"sustainability-risk":  sustainabilityRiskSuccessCriterion,
		"compounding-risk":     compoundingRiskSuccessCriterion,
	}

	if len(document.SuccessCriteria) != len(ported) {
		t.Fatalf("reference pins %d criteria, the port has %d",
			len(document.SuccessCriteria), len(ported))
	}
	for ruleID, want := range document.SuccessCriteria {
		got, ok := ported[ruleID]
		if !ok {
			t.Errorf("rule %q has no ported success criterion", ruleID)
			continue
		}
		if got != want {
			t.Errorf("rule %q success criterion:\n  reference: %q\n  port:      %q", ruleID, want, got)
		}
	}
}

// TestRuleEvaluatorsMatchTheReference is the parity claim.
//
// Every field of every fired recommendation is compared, and evidence values
// are compared BITWISE rather than with ==, because the interesting failures
// are last-bit ones: a rounded evidence value that differs in its final bit is
// a different number in the stored evidence_json, and == would also equate
// +0.0 with -0.0, which round() deliberately keeps apart.
func TestRuleEvaluatorsMatchTheReference(t *testing.T) {
	document := loadRulesGolden(t)
	now := time.Date(2026, 9, 2, 12, 0, 0, 0, time.UTC)

	var compared, fired int
	firedPerRule := map[string]int{}
	declinedPerRule := map[string]int{}

	for _, testCase := range document.Cases {
		snapshot := decodeSnapshot(t, testCase.Snapshot)

		for _, evaluator := range orderedRuleEvaluators {
			want, ok := testCase.Results[evaluator.id]
			if !ok {
				t.Fatalf("case %q has no reference result for rule %q", testCase.Name, evaluator.id)
			}
			compared++

			got, err := evaluator.evaluate(snapshot, now)
			if err != nil {
				t.Fatalf("case %q rule %q: unexpected error: %v", testCase.Name, evaluator.id, err)
			}

			if want == nil {
				declinedPerRule[evaluator.id]++
				if got != nil {
					t.Errorf("case %q rule %q: reference did not fire, the port fired (severity %q, rationale %q)",
						testCase.Name, evaluator.id, got.Severity, got.Rationale)
				}
				continue
			}
			fired++
			firedPerRule[evaluator.id]++
			if got == nil {
				t.Errorf("case %q rule %q: reference fired (%q), the port did not",
					testCase.Name, evaluator.id, want.Rationale)
				continue
			}

			if got.RuleID != want.RuleID {
				t.Errorf("case %q rule %q: rule_id %q, want %q", testCase.Name, evaluator.id, got.RuleID, want.RuleID)
			}
			if got.TeamID != want.TeamID || got.OrgID != want.OrgID {
				t.Errorf("case %q rule %q: ids (%q,%q), want (%q,%q)",
					testCase.Name, evaluator.id, got.TeamID, got.OrgID, want.TeamID, want.OrgID)
			}
			if got.Severity != want.Severity {
				t.Errorf("case %q rule %q: severity %q, want %q", testCase.Name, evaluator.id, got.Severity, want.Severity)
			}
			if got.Title != want.Title {
				t.Errorf("case %q rule %q: title %q, want %q", testCase.Name, evaluator.id, got.Title, want.Title)
			}
			if got.Rationale != want.Rationale {
				t.Errorf("case %q rule %q: rationale\n  got:  %q\n  want: %q",
					testCase.Name, evaluator.id, got.Rationale, want.Rationale)
			}
			if got.SuccessCriterion != want.SuccessCriterion {
				t.Errorf("case %q rule %q: success_criterion\n  got:  %q\n  want: %q",
					testCase.Name, evaluator.id, got.SuccessCriterion, want.SuccessCriterion)
			}

			if len(got.Evidence) != len(want.Evidence) {
				t.Errorf("case %q rule %q: %d evidence rows, want %d",
					testCase.Name, evaluator.id, len(got.Evidence), len(want.Evidence))
				continue
			}
			for index, wantRef := range want.Evidence {
				gotRef := got.Evidence[index]
				if gotRef.MetricTable != wantRef.MetricTable || gotRef.Field != wantRef.Field {
					t.Errorf("case %q rule %q evidence[%d]: (%s,%s), want (%s,%s)",
						testCase.Name, evaluator.id, index,
						gotRef.MetricTable, gotRef.Field, wantRef.MetricTable, wantRef.Field)
				}
				if gotRef.TeamID != wantRef.TeamID {
					t.Errorf("case %q rule %q evidence[%d]: team_id %q, want %q",
						testCase.Name, evaluator.id, index, gotRef.TeamID, wantRef.TeamID)
				}
				wantValue := parseGoldenBits(t, wantRef.ValueBits)
				// Cross-check the corpus's two encodings against each other on
				// the values where both are exact. A generator that wrote the
				// bits of one value and the hex of another would otherwise be
				// invisible: the test would happily compare against a
				// self-consistent fiction.
				if !math.IsNaN(wantValue) {
					if viaHex := parsePythonHexFloat(t, wantRef.ValueHex); math.Float64bits(viaHex) != math.Float64bits(wantValue) {
						t.Fatalf("case %q rule %q evidence[%d]: corpus disagrees with itself, "+
							"value_hex %q is %#016x but value_bits is %s",
							testCase.Name, evaluator.id, index, wantRef.ValueHex,
							math.Float64bits(viaHex), wantRef.ValueBits)
					}
				}
				if math.Float64bits(gotRef.Value) != math.Float64bits(wantValue) {
					t.Errorf("case %q rule %q evidence[%d] %s: value %v (%#016x), want %v (%#016x)",
						testCase.Name, evaluator.id, index, gotRef.Field,
						gotRef.Value, math.Float64bits(gotRef.Value),
						wantValue, math.Float64bits(wantValue))
				}
			}
		}
	}

	// Anti-vacuity. Each of these has a distinct bypass, so each is asserted.
	//
	// An empty corpus, a corpus in which nothing fires, or one in which some
	// rule never fires would all let this test report ok while proving much
	// less than it claims. The per-rule counts are the load-bearing part: a
	// corpus where compounding-risk never fired would leave its severity
	// mapping and both of its rationale branches entirely unchecked, and the
	// aggregate "1240 firings" would hide that completely.
	if compared == 0 {
		t.Fatal("no comparisons ran; the corpus is empty and this test proved nothing")
	}
	for _, evaluator := range orderedRuleEvaluators {
		if firedPerRule[evaluator.id] == 0 {
			t.Errorf("rule %q never fired in the corpus, so its fired-path fields "+
				"(severity, title, rationale, evidence) are unchecked", evaluator.id)
		}
		if declinedPerRule[evaluator.id] == 0 {
			t.Errorf("rule %q fired in every case, so none of its guards are "+
				"exercised -- a port that always fires would pass", evaluator.id)
		}
	}
	t.Logf("compared %d (case, rule) pairs across %d cases: %d fired, %d declined",
		compared, len(document.Cases), fired, compared-fired)
	for _, evaluator := range orderedRuleEvaluators {
		t.Logf("  %-22s fired %4d  declined %4d", evaluator.id,
			firedPerRule[evaluator.id], declinedPerRule[evaluator.id])
	}
}

// TestCompoundingRiskPathsAreBothExercised pins the coverage that matters most
// in the only rule with two firing paths and the only one that emits
// "critical".
//
// TestRuleEvaluatorsMatchTheReference already compares every case, but it
// cannot tell that the composite path shadowed the proxy path -- both paths
// produce a compounding-risk row with the same title, so a port that dropped
// the shadowing rule would still fire, and would differ only in the rationale
// of cases the corpus might not contain.
func TestCompoundingRiskPathsAreBothExercised(t *testing.T) {
	document := loadRulesGolden(t)

	var composite, proxy, critical int
	for _, testCase := range document.Cases {
		result := testCase.Results["compounding-risk"]
		if result == nil {
			continue
		}
		switch {
		case strings.HasPrefix(result.Rationale, "Compounding Risk"):
			composite++
		case strings.HasPrefix(result.Rationale, "Hotspot complexity delta"):
			proxy++
		default:
			t.Errorf("case %q: unrecognised compounding-risk rationale %q", testCase.Name, result.Rationale)
		}
		if result.Severity == "critical" {
			critical++
		}
	}

	if composite == 0 {
		t.Error("no case exercises the CHAOS-1641 composite path")
	}
	if proxy == 0 {
		t.Error("no case exercises the legacy hotspot-proxy fallback path")
	}
	if critical == 0 {
		t.Error(`no case produces severity "critical"; compounding-risk is the only ` +
			`rule that can, so the "high" -> critical mapping is otherwise unchecked`)
	}
	t.Logf("compounding-risk firings: composite %d, proxy %d, critical %d", composite, proxy, critical)
}

// TestEveryEvidenceValueIsAPythonFloat is the frozen half of a guard whose live
// half runs in the generator.
//
// The other end of this argument is in internal/pythonparity/jsoninsertionorder.go
// under "INTS ARE ENCODED, NOT REFUSED, AND THAT IS A SHARP EDGE TOO". That
// encoder writes 100 for a Python int and 100.0 for a float, correctly, because
// it reproduces json.dumps and json.dumps(100) is 100. It therefore cannot
// catch an evidence value that arrives as an int, and must not try.
//
// Go cannot catch it either: EvidenceRef.Value is typed float64, so the port is
// structurally unable to produce an int and a Go test asserting "this float64
// is a float" would be asserting the compiler, not the reference.
//
// The exposure is Python-side. All eleven `value=` sites pass an explicit
// ndigits to round(), and round(float, ndigits) returns a float -- but round(x)
// WITHOUT ndigits returns an int. Drop one argument and the stored column goes
// from 100.0 to 100 silently.
//
// The generator refuses to WRITE such a corpus. This test refuses to ACCEPT
// one, which is a different failure: a corpus regenerated against a changed
// reference, hand-edited, or restored from an older revision would carry the
// int and no live check would be running at that moment.
func TestEveryEvidenceValueIsAPythonFloat(t *testing.T) {
	document := loadRulesGolden(t)

	var checked int
	for _, testCase := range document.Cases {
		for ruleID, result := range testCase.Results {
			if result == nil {
				continue
			}
			for _, ref := range result.Evidence {
				checked++
				if ref.ValueType != "float" {
					t.Errorf("case %q rule %q field %q: Python type %q, want \"float\" -- "+
						"a `value=round(x, N)` site has probably lost its ndigits, which "+
						"makes round() return an int and silently changes the stored "+
						"evidence_json from e.g. 100.0 to 100 (see jsoninsertionorder.go, "+
						"\"INTS ARE ENCODED, NOT REFUSED\")",
						testCase.Name, ruleID, ref.Field, ref.ValueType)
				}
			}
		}
	}

	if checked == 0 {
		t.Fatal("no evidence values carried a recorded type; either the corpus fired " +
			"no rules or value_type is missing, and this guard proved nothing")
	}
	// Cross-check against the count the generator recorded, so a corpus that
	// silently lost most of its evidence rows fails here rather than passing on
	// the handful that remain.
	if document.EvidenceValuesTypeChecked != checked {
		t.Errorf("generator type-checked %d evidence values, this test found %d; "+
			"the corpus and its own provenance disagree",
			document.EvidenceValuesTypeChecked, checked)
	}
	t.Logf("evidence values with a recorded Python type of float: %d", checked)
}
